function files(){if(!env.BUCKET)throw new AppError('FILES_NOT_READY','照片存储暂不可用。',503);return env.BUCKET;}
function validId(id:string){if(typeof id!=='string'||! /^[a-f0-9-]{36}$/.test(id))throw new AppError('INVALID_OPERATION','迁移操作标识无效。',400);}
function metadata(){return{stageVideos:stageSourceMetadata,stageResearch:stageResearchMetadata,groupPlaceholders:groupPlaceholderMetadata,stageSupplements:stageSupplementMetadata};}
function ordered(t:NativeTables){return Object.fromEntries(tables.map(k=>[k,{fields:t[k].fields.slice().sort((a,b)=>a.field_id.localeCompare(b.field_id)),records:t[k].records.slice().sort((a,b)=>a.recordId.localeCompare(b.recordId))}])) as NativeTables;}
async function contentHash(d:ArchiveData){return hash({tables:ordered(d.tables),journal:d.journal,locks:d.locks,siteMetadata:d.siteMetadata});}
async function candidate(userId:string,id:string){validId(id);await ownControl(userId);const s=await nativeDb().prepare('SELECT * FROM idol_native_snapshots WHERE id=? AND owner_id=?').bind(id,userId).first<Snapshot>();if(!s)throw new AppError('MIGRATION_NOT_FOUND','找不到这次迁移。',404);const m=JSON.parse(s.manifest_json) as Meta;if(m.kind!=='idol.cutover.v1')throw new AppError('MIGRATION_NOT_FOUND','该记录不是切换操作。',404);return{s,m};}
