async function withCutoverLock<T>(id:string,work:(markWrite:()=>void)=>Promise<T>){const db=nativeDb(),op=crypto.randomUUID();await db.prepare('INSERT OR IGNORE INTO idol_archive_step_locks(id,operation_id,created_at) VALUES(?,?,?)').bind(id,op,Date.now()).run();const row=await db.prepare('SELECT operation_id FROM idol_archive_step_locks WHERE id=?').bind(id).first<{operation_id:string}>();if(row?.operation_id!==op)throw new AppError('MIGRATION_BUSY','上一项操作尚未确认，请先核对。',409);let release=false,mutationStarted=false;try{const result=await work(()=>{mutationStarted=true;});release=true;return result;}catch(e){const error=e&&typeof e==='object'?e as {name?:unknown;message?:unknown}:{};const name=typeof error.name==='string'&&['Error','TypeError','RangeError','SyntaxError','AbortError','TimeoutError'].includes(error.name)?error.name:'UnknownError';const message=typeof error.message==='string'?error.message:'';console.error(JSON.stringify({event:'idol_cutover_failure',mutationStarted,errorName:name,code:e instanceof AppError&&/^[A-Z0-9_]{1,64}$/.test(e.code)?e.code:null,category:/D1_ERROR|SQLITE_/i.test(message)?'d1':/R2|bucket/i.test(message)?'r2':/memory|allocation/i.test(message)?'memory':/network|fetch|connection|timeout/i.test(message)?'network':'other'}));if(!mutationStarted&&e instanceof AppError&&['SAVES_PENDING','SOURCE_READ_FAILED','MIGRATION_STATE','BACKUP_NOT_READY','RESTORE_CHECK_REQUIRED','SOURCE_CHANGED','NEW_PHOTOS_REQUIRE_BACKUP','SEAL_REQUIRED','SEAL_MISMATCH','MIGRATION_LIMIT','IDEMPOTENCY_CONFLICT','ARCHIVE_TOO_LARGE'].includes(e.code))release=true;throw e;}finally{if(release)await db.prepare('DELETE FROM idol_archive_step_locks WHERE id=? AND operation_id=?').bind(id,op).run();}}
async function noPending(userId:string){const db=nativeDb(),a=await db.prepare('SELECT count(*) n FROM idol_record_locks').first<{n:number}>(),b=await db.prepare(`SELECT count(*) n FROM idol_saves WHERE user_id=? AND status NOT IN ${terminal}`).bind(userId).first<{n:number}>();if(a?.n||b?.n)throw new AppError('SAVES_PENDING','还有未确认的保存，请先核对，暂不切换。',409);}
async function budget(extra=0,enforce=true,provisional:Quarantine[]=[]){const other=await archiveObjectBytes(provisional)+await archiveD1Bytes();const rows=await nativeDb().prepare('SELECT object_key,min(byte_length) low,max(byte_length) high,count(DISTINCT sha256) hashes FROM idol_native_media WHERE object_key IS NOT NULL GROUP BY object_key').all<{object_key:string;low:number;high:number;hashes:number}>();let photos=0;for(const r of rows.results){if(!Number.isSafeInteger(r.high)||r.low!==r.high||r.hashes!==1)throw new AppError('MIGRATION_BUDGET_UNKNOWN','照片容量核对失败，已停止。',409);photos+=r.high;}if(enforce&&(other+extra>CUTOVER_OTHER_BYTES||photos+other+extra>ARCHIVE_LIMITS.maxTotalBytes))throw new AppError('MIGRATION_LIMIT','达到本轮存储边界，已停止。',409);return{other,photos,otherLimit:CUTOVER_OTHER_BYTES,totalLimit:ARCHIVE_LIMITS.maxTotalBytes,otherRemaining:CUTOVER_OTHER_BYTES-other,totalRemaining:ARCHIVE_LIMITS.maxTotalBytes-photos-other};}
function reportMatches(r:any,m:any,summary:any,data:ArchiveData){const allowed=['formatVersion','completeBackup','missingPhotoTokens','archiveId','manifestHash','dataSha256','restoredRecords','fieldValues','protectedValues','journalRows','photoTokens','decodedUniqueImages','decodedFrames','photoReferences','photoBytes','fieldMismatches','photoFailures','sqliteIntegrity','sourceNetworkUsed','verifiedAt'];if(!r||Object.keys(r).length!==allowed.length||Object.keys(r).some(k=>!allowed.includes(k))||new TextEncoder().encode(JSON.stringify(r)).length>4000)throw new AppError('RESTORE_CHECK_REQUIRED','恢复报告字段不完整或超出范围。',409);const protectedIds=new Set(['fld3SVWhWc','fld1yLzS5g','fld6bHl8sq','fld38CJY2U','fld641ausT','fld4yOdHT5','fld3QKrpLN','fld7E8yx1a','fld49NJY1j','fld1L5cSac','fld3y0fn7i']);let fields=0,protectedValues=0;for(const t of tables)for(const row of data.tables[t].records){fields+=Object.keys(row.fields).length;protectedValues+=Object.keys(row.fields).filter(k=>protectedIds.has(k)).length;}if(r.fieldValues!==fields||r.protectedValues!==protectedValues||r.photoReferences!==m.references.length||!Number.isSafeInteger(r.decodedFrames)||r.decodedFrames<r.decodedUniqueImages)throw new AppError('RESTORE_CHECK_REQUIRED','字段或逐帧恢复验收不完整。',409);const count=Object.values(summary.counts as Record<string,number>).reduce((a,b)=>a+b,0);if(!r||r.formatVersion!=='idol.restore-report.v1'||r.completeBackup!==true||r.missingPhotoTokens!==0||r.archiveId!==m.id||r.manifestHash!==m.manifestHash||r.dataSha256!==m.data.sha256||r.restoredRecords!==count||r.journalRows!==summary.journalCount||r.photoTokens!==m.photos.length||r.photoBytes!==m.photos.reduce((n:number,p:any)=>n+p.byteLength,0)||r.decodedUniqueImages!==new Set(m.photos.map((p:any)=>p.sha256)).size||r.fieldMismatches!==0||r.photoFailures!==0||r.sqliteIntegrity!=='ok'||r.sourceNetworkUsed!==false||!Number.isFinite(Date.parse(r.verifiedAt)))throw new AppError('RESTORE_CHECK_REQUIRED','请先完成完整备份的独立恢复验收。',409);}
async function lease(userId:string,s:Snapshot,m:Meta){const c=await ownControl(userId);if(!c||c.mode!=='frozen'||c.active_snapshot||c.run_id!==s.id||c.epoch!==m.freezeEpoch)throw new AppError('MIGRATION_CHANGED','资料来源状态已变化，请重新核对。',409);return c;}
function guard(s:Snapshot,m:Meta,frozen:boolean){return{sql:`EXISTS (SELECT 1 FROM idol_native_snapshots p JOIN idol_storage_control c ON c.id='main' WHERE p.id=? AND p.owner_id=? AND p.status=? AND p.manifest_json=? AND c.owner_id=? AND c.mode=? AND c.epoch=? AND c.active_snapshot IS NULL${frozen?' AND c.run_id=?':''})`,args:[s.id,s.owner_id,s.status,s.manifest_json,s.owner_id,frozen?'frozen':'feishu',frozen?m.freezeEpoch:m.expectedEpoch,...(frozen?[s.id]:[])]};}
