 if(b.ownerId!==userId||b.sourceRunId!==m.sourceRunId||b.candidateId!==s.id||b.attemptId!==probe.attemptId||!['search-all-fields-open-id-no-auto-v1',migrationReadApi].includes(b.readApi??'')||!['preflight','capture','activation'].includes(b.purpose)||!Number.isSafeInteger(b.epoch)||p.index!==1||probe.part.key!==`archives/${m.sourceRunId}/read-pages/${s.id}/${b.purpose}/${b.epoch}/${probe.attemptId}/1.json.gz`||p.table!=='groups'||p.kind!=='records'||p.cursor!==null)throw new AppError('CHECKPOINT_MISMATCH','字段比较证据不属于本次操作。',409);
